// .lighthouserc-mobile.cjs
// Mobile Lighthouse CI configuration for Date My Dish — PR gate
// URLs are generated by scripts/generate-lighthouse-urls.cjs --mode=changed

const fs = require('fs');
const path = require('path');

let urls;
try {
  urls = JSON.parse(
    fs.readFileSync(path.join(__dirname, '.lighthouse-urls.json'), 'utf8')
  );
} catch {
  // Fallback if URL generation hasn't run
  urls = ['http://localhost:8788/en/', 'http://localhost:8788/fr/'];
}

module.exports = {
  ci: {
    collect: {
      startServerCommand: 'npx wrangler dev --port 8788',
      startServerReadyPattern: 'Ready on',
      startServerReadyTimeout: 30000,
      url: urls,
      numberOfRuns: 1,
      settings: {
        chromeFlags: '--no-sandbox --disable-dev-shm-usage',
        // No preset = Lighthouse mobile default (4x CPU throttle, simulated slow 4G)
        blockedUrlPatterns: [
          'https://s.pinimg.com/*',
          'https://ct.pinterest.com/*',
          'https://static.cloudflareinsights.com/*',
          'https://cloudflareinsights.com/*',
        ],
      },
    },
    assert: {
      assertions: {
        // All warn (not error) — establishing mobile baselines
        'categories:seo': ['warn', { minScore: 0.9 }],
        'categories:accessibility': ['warn', { minScore: 0.9 }],

        // Lower thresholds for mobile (CPU/network throttling reduces scores)
        'categories:performance': ['warn', { minScore: 0.8, aggregationMethod: 'median' }],
        'categories:best-practices': ['warn', { minScore: 0.8 }],

        // Core Web Vitals
        'cumulative-layout-shift': ['warn', { maxNumericValue: 0.1, aggregationMethod: 'median' }],
      },
    },
    upload: {
      target: 'temporary-public-storage',
    },
  },
};
